// ── 1. Chain of Responsibility — Express middleware ─────────────
const express = require('express');
const app = express();

// Each handler is a link in the chain
app.use((req, res, next) => {
  console.log(`[logger] ${req.method} ${req.url}`);
  next(); // pass to next link
});

app.use((req, res, next) => {
  if (!req.headers['x-api-key']) {
    return res.status(401).json({ error: 'Unauthorized' }); // chain stops here
  }
  next();
});

app.get('/data', (req, res) => res.json({ ok: true }));

// ── 2. Command — Redux-style action dispatch ────────────────────
function createStore(reducer, initial) {
  let state = initial;
  const listeners = [];                      // Observer list
  return {
    getState: () => state,
    dispatch(action) {                       // action = Command object
      state = reducer(state, action);
      listeners.forEach(fn => fn());         // notify all Observers
    },
    subscribe(fn) { listeners.push(fn); },  // register Observer
  };
}

const store = createStore(                  // Singleton
  (state, action) => {
    if (action.type === 'ADD') return { count: state.count + action.by };
    return state;
  },
  { count: 0 }
);

store.subscribe(() => console.log('state:', store.getState()));
store.dispatch({ type: 'ADD', by: 5 });   // state: { count: 5 }
store.dispatch({ type: 'ADD', by: 3 });   // state: { count: 8 }

// ── 3. Decorator — Higher-Order Component ──────────────────────
function withLogging(WrappedFn) {           // Decorator factory
  return function decorated(...args) {
    console.log(`Calling ${WrappedFn.name} with`, args);
    const result = WrappedFn(...args);
    console.log(`Result:`, result);
    return result;
  };
}

const add = (a, b) => a + b;
const loggedAdd = withLogging(add);         // Wrapped — same interface, extra behaviour
console.log(loggedAdd(2, 3));              // logs call + result, returns 5

// ── 4. Builder — TypeORM-style query builder ───────────────────
class QueryBuilder {
  constructor(table) {
    this._table = table;
    this._conditions = [];
    this._joins = [];
    this._limit = null;
  }
  where(cond)      { this._conditions.push(cond); return this; }
  leftJoin(table)  { this._joins.push(`LEFT JOIN ${table}`); return this; }
  take(n)          { this._limit = n; return this; }
  build() {
    const where = this._conditions.length
      ? `WHERE ${this._conditions.join(' AND ')}`
      : '';
    const join  = this._joins.join(' ');
    const limit = this._limit ? `LIMIT ${this._limit}` : '';
    return `SELECT * FROM ${this._table} ${join} ${where} ${limit}`.trim();
  }
}

const sql = new QueryBuilder('users')
  .leftJoin('orders ON orders.user_id = users.id')
  .where('users.active = true')
  .where('orders.total > 100')
  .take(10)
  .build();
console.log(sql);
// SELECT * FROM users LEFT JOIN orders ON ... WHERE users.active = true AND orders.total > 100 LIMIT 10

// ── Promise as State Machine ────────────────────────────────────
// States: pending → fulfilled | rejected  (terminal, one-way)
const p = new Promise((resolve, reject) => {
  setTimeout(() => resolve('done'), 100);
});
// Calling resolve again is a no-op — FSM already in terminal state
// p is still fulfilled with 'done'

// ── Node Stream: Decorator layers ──────────────────────────────
// Each .pipe() wraps the data stream with new behaviour
// (In Node.js internals, Transform implements Readable+Writable Adapter)
//
//   fs.createReadStream(src)
//     .pipe(zlib.createGzip())         // Decorator: compress
//     .pipe(crypto.createCipher(...))  // Decorator: encrypt
//     .pipe(fs.createWriteStream(dst)) // Adapter: write to file
//
// All nodes share the same pipe-able interface — Composite/Adapter

// ── Strategy via render-prop style ─────────────────────────────
function fetchData(url, renderResult) {    // renderResult = Strategy
  return fetch(url)
    .then(r => r.json())
    .then(data => renderResult(data));     // algorithm is swappable
}

fetchData('/api/users', users =>
  console.log('Table:', users.map(u => u.name))
);
fetchData('/api/users', users =>
  console.log('Count:', users.length)     // different strategy, same fetch logic
);

// ── Composite — React-like tree ─────────────────────────────────
// Each node: { type, props, children[] } — leaf and branch share shape
const page = {
  type: 'Page',
  children: [
    { type: 'Header', children: [] },
    { type: 'Section', children: [
      { type: 'Button', children: [] },
      { type: 'Button', children: [] },
    ]},
  ],
};

function render(node, depth = 0) {
  console.log(' '.repeat(depth * 2) + node.type);
  node.children.forEach(child => render(child, depth + 1)); // uniform recursion
}
render(page);
// Page
//   Header
//   Section
//     Button
//     Button
